    or horizontally (not diagonally).
    Args:
        grid: List of lists of ints (0 or 1). May be empty.
    Returns:
        Integer count of islands.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    visited = [[False] * cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            # explore neighbors
            if i > 0 and grid[i-1][j] == 1 and not visited[i-1][j]:
                stack.append((i-1, j))
            if i < rows-1 and grid[i+1][j] == 1 and not visited[i+1][j]:
                stack.append((i+1, j))
            if j > 0 and grid[i][j-1] == 1 and not visited[i][j-1]:
                stack.append((i, j-1))
            if j < cols-1 and grid[i][j+1] == 1 and not visited[i][j+1]:
                stack.append((i, j+1))
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                dfs(i, j)
    return count

