{"task_id": "T35", "code": "def solve(grid):
    """Count islands in a possibly non‑rectangular grid.
    Connections are 4‑directional (up, down, left, right)."""
    if not grid:
        return 0
    visited = set()
    n = len(grid)
    def get_neighbors(i, j):
        # up
        if i > 0 and j < len(grid[i-1]):
            yield i-1, j
        # down
        if i+1 < n and j < len(grid[i+1]):
            yield i+1, j
        # left
        if j > 0:
            yield i, j-1
        # right
        if j+1 < len(grid[i]):
            yield i, j+1
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            for nx, ny in get_neighbors(x, y):
                if grid[nx][ny] == 1 and (nx, ny) not in visited:
                    stack.append((nx, ny))
    islands = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and (i, j) not in visited:
                dfs(i, j)
                islands += 1
    return islands
