            yield i-1, j
        # down
        if i+1 < n and j < len(grid[i+1]):
            yield i+1, j
        # left
        if j > 0:
            yield i, j-1
        # right
        if j+1 < len(grid[i]):
            yield i, j+1
    def dfs(i, j):
