    """Evaluate an expression in Reverse Polish Notation.
    Supports '+', '-', '*', '/' where division truncates toward zero.
    Handles large integers without converting to float.
    """
    def div_trunc(a, b):
        # Truncate toward zero without using float division.
        if b == 0:
            raise ZeroDivisionError('division by zero')
        sign = 1 if a * b >= 0 else -1
        return sign * (abs(a) // abs(b))
    stack = []
    for t in tokens:
        if t in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            else:  # '/'
                res = div_trunc(a, b)
