def solve(intervals):
    # Guard against None or non-iterable input
    if not intervals:
        return []
    # Ensure each interval is a list of two numbers
    cleaned = []
    for inter in intervals:
        if isinstance(inter, (list, tuple)) and len(inter) == 2:
            cleaned.append([inter[0], inter[1]])
    if not cleaned:
        return []
    cleaned.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = cleaned[0]
    for start, end in cleaned[1:]:
        if start <= cur_end:
            cur_end = max(cur_end, end)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end
    merged.append([cur_start, cur_end])
    return merged

