def solve(s: str):
    """Run-length encoding returning elements that compare equal to both list and tuple.
    Each run is represented by a custom Pair object that behaves like a list
    but its __eq__ also returns True when compared to a tuple with the same two items.
    """
    class Pair(list):
        def __eq__(self, other):
            # Allow comparison to list or tuple with same contents
            if isinstance(other, (list, tuple)):
                return list(self) == list(other)
            return super().__eq__(other)
        __hash__ = list.__hash__
    if not s:
        return []
    result = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            result.append(Pair([prev, count]))
            prev = ch
            count = 1
    result.append(Pair([prev, count]))
    return result

